class Punto implements Serializable {
    int x;
    int y;
}

Punto p = new Punto();
p.x = 3;
p.y = 4;
// ObjectOutputStream.writeObject(p) funciona porque Punto implementa Serializable

Punto p = new Punto();
p.x = 1;
try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("p.ser"))) {
    oos.writeObject(p);
    oos.writeObject(p); // la misma referencia, otra vez
}
try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("p.ser"))) {
    Punto a = (Punto) ois.readObject();
    Punto b = (Punto) ois.readObject();
    System.out.println(a == b); // true
}

class Sesion implements Serializable {
    private static final long serialVersionUID = 1L;
    String usuario;
    transient String tokenTemporal;
    static int sesionesActivas = 0;
}
// tokenTemporal vuelve a null al deserializar (valor por defecto), aunque tuviera un valor al serializar
// sesionesActivas nunca viaja: pertenece a la clase, no al objeto

